Translate("zhCN", "the-cauldron", {
	title = "大熔炉",
	aliases = { "熔炉" },
	sections = {
		{
			title = "概述",
			text = [=[大熔炉是{link:searing-gorge}灼热峡谷{/link}中央的巨坑，是{link:dark-iron-dwarves}黑铁矮人{/link}自炎魔之王降临以来的杰作。它的坑壁以黑色岩石的阶地层层下陷，坑的边缘立着它的主人们的挖掘机械，以及四座守卫着每一条通道的哨塔。重型战争傀儡在它的山坡上巡逻。奴隶们在监工的注视下把矿石从深处运上来。火焰{link:elements}元素{/link}在它的底层自由行走。在它西侧的一个洞穴里，地下市场的商人与黑铁矮人做生意，对任何人都不问来历。]=],
		},
	},
})

Translate("zhCN", "the-slag-pit", {
	title = "熔渣之池",
	aliases = { "熔渣池" },
	sections = {
		{
			title = "概述",
			text = [=[熔渣之池是{link:the-cauldron}大熔炉{/link}下方的矿洞。它的隧道热得足以让毫无准备的人送命，{link:dark-iron-dwarves}黑铁矮人{/link}在那里驱使他们的俘虏不停劳作。俘虏中有{link:ironforge}铁炉堡{/link}的考古学家，他们的心智已被扭曲，只为一项任务而活。在深处，靠近一座古老的祭坛，他们为一具巨大的{link:blackrock-mountain}黑石{/link}傀儡辛苦劳作。熔岩之河流过下层的大厅，在其中游动的火焰蜥蜴十分危险，{link:thorium-brotherhood}瑟银兄弟会{/link}在它们的数量减少之前不肯派自己的挖掘者下去。叛徒{link:overseer-maltorius}玛托留斯{/link}在这里指挥黑铁矮人的工队。]=],
		},
	},
})

Translate("zhCN", "firewatch-ridge", {
	title = "观火岭",
	sections = {
		{
			title = "概述",
			text = [=[观火岭是{link:searing-gorge}灼热峡谷{/link}西部的{link:razorfen-downs}高地{/link}，俯瞰{link:the-cauldron}大熔炉{/link}。{link:dark-iron-dwarves}黑铁矮人{/link}在这里设有他们最大的营地，周围是他们的傀儡和焦土丘陵上的巨型蜘蛛。更高处的西北方，{link:twilight-s-hammer}暮光之锤{/link}在一个洞穴旁建起了自己的营地。他们的偶像崇拜者携带着{red:ragnaros}拉格纳罗斯{/red}的象征，他们的首领是一个自称{link:highlord-mastrogonde}玛斯托格{/link}的{link:humans}人类{/link}。他们山头上的一个笼子里悬着一个{link:night-elves}暗夜精灵{/link}的灵魂，他们以亵渎之罪处决了他。]=],
		},
	},
})

Translate("zhCN", "grimesilt-dig-site", {
	title = "煤渣挖掘场",
	aliases = { "煤渣" },
	sections = {
		{
			title = "概述",
			text = [=[煤渣挖掘场是{link:ironforge}铁炉堡{/link}{link:dwarves}矮人{/link}的一处发掘地，由希望找到焦土秘密的人开凿于峡谷东部。{link:dark-iron-dwarves}黑铁矮人{/link}从他们手中夺走了它。如今黑铁的地质学家在坑中劳作，据说他们干活时会用上一种奇怪的魔法。铁炉堡的队伍所剩无几。一个受伤的矮人在挖掘坑的底部被人发现，另一个之所以还活着，只是因为他躲进了一间茅房，被锁在了里面。名为桑塔拉的石头最初就是在煤渣被发现的。]=],
		},
	},
})

Translate("zhCN", "the-sea-of-cinders", {
	title = "灰烬之海",
	aliases = { "灰烬海" },
	sections = {
		{
			title = "概述",
			text = [=[灰烬之海是峡谷南部一片平坦焦黑的{link:burning-steppes}平原{/link}，位于{link:blackrock-mountain}黑石山{/link}北坡之下。那里寸草不生。灰烬随着每一阵风飘过平原，脚下的大地仍在冒烟。通往山门的道路穿过这里，在那条路上等候的人从不透露自己的心思。一个{link:humans}人类{/link}女子在这里扎了一座小营地，以一个地狱火为护卫，她对地下市场的商人没什么好感。]=],
		},
	},
})

Translate("zhCN", "blackchar-cave", {
	title = "黑炭谷",
	sections = {
		{
			title = "概述",
			text = [=[黑炭谷的洞口开在峡谷西南的丘陵中，离{link:blackrock-mountain}黑石山{/link}的山坡不远。它的入口被封住了，住在峡谷里的人谁也不肯说是谁封的，又是为什么。{link:thorium-point}瑟银哨塔{/link}的{link:dwarves}矮人{/link}对它闭口不谈。{link:dark-iron-dwarves}黑铁矮人{/link}也不守卫它。它是这片焦土众多沉默之一，明智的旅人不会去打扰它。]=],
		},
	},
})

Translate("zhCN", "tanner-camp", {
	title = "制皮匠营地",
	sections = {
		{
			title = "概述",
			text = [=[制皮匠营地是峡谷东南部一顶孤零零的帐篷，远离任何友好的城墙。它属于{link:sarah-tanner}萨拉·坦尼{/link}，一位懂得把{link:elements}元素{/link}之力缚入皮革的制皮大师。她为何选择住在这里，是她自己的事。她的帐篷后面，一条长长的通道蜿蜒伸入丘陵，尽头就是{link:margol-the-rager}狂暴的玛尔戈{/link}的巢穴。]=],
		},
	},
})

Translate("zhCN", "dustfire-valley", {
	title = "尘火谷",
	aliases = { "石坝小径" },
	sections = {
