Translate("zhCN", "thorium-brotherhood", {
	title = "瑟银兄弟会",
	aliases = { "瑟银兄弟会的矮人" },
	sections = {
		{
			title = "概述",
			text = [=[瑟银兄弟会是一群与{link:blackrock-mountain}黑石山{/link}中的同族决裂的{link:dark-iron-dwarves}黑铁矮人{/link}。他们出于自己的意愿离开了深渊的厅堂，并坚称自己与那些仍在侍奉{red:ragnaros}拉格纳罗斯{/red}的黑铁矮人毫无相似之处。他们首先是矿工和铁匠，据说他们的铁匠是世上最出色的铁匠之一。他们的监督者承认，近来他们也不得不成为士兵。]=],
		},
		{
			title = "瑟银哨塔",
			text = [=[兄弟会的大本营是{link:thorium-point}瑟银哨塔{/link}，一座位于{link:the-cauldron}大熔炉{/link}上方悬崖上的设防城镇。他们从那里监视着峡谷中{link:dark-iron-dwarves}黑铁矮人{/link}的一举一动。他们悬赏他们昔日的同族，出钱寻回被盗的工具，并雇佣外人去完成他们人手不足、无力亲自完成的杀戮。]=],
		},
		{
			title = "锻炉的秘密",
